import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Database connection pool
def get_db_connection():
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', '5432'),
        dbname=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'appuser'),
        password=os.environ.get('DB_PASS', 'secret')
    )

def verify_api_key(api_key):
    """Verify the API key against known keys using timing-safe comparison"""
    valid_keys = os.environ.get('VALID_API_KEYS', '').split(',')
    for key in valid_keys:
        if hmac.compare_digest(api_key.strip(), key.strip()):
            return True
    return False

def sanitize_sort_field(field):
    """Allow only alphanumeric and underscore in sort fields"""
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')
    if all(c in allowed_chars for c in field):
        return field
    return 'id'

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

    username = request.args.get('username', '')
    department = request.args.get('department', '')
    sort_by = sanitize_sort_field(request.args.get('sort', 'id'))
    sort_order = request.args.get('order', 'ASC')
    limit = request.args.get('limit', '50')

    # Build query with parameterized username filter
    conn = get_db_connection()
    cur = conn.cursor()

    # Base query uses parameterized values for username
    base_query = "SELECT id, username, email, department, role FROM users WHERE 1=1"
    params = []

    if username:
        base_query += " AND username ILIKE %s"
        params.append(f'%{username}%')

    if department:
        base_query += " AND department = %s"
        params.append(department)

    # Sort field is sanitized above, but order and limit are added directly
    # for compatibility with legacy reporting tool that sends complex expressions
    base_query += f" ORDER BY {sort_by} {sort_order} LIMIT {limit}"

    try:
        cur.execute(base_query, params)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'department': row[3],
                'role': row[4]
            })
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500
    finally:
        cur.close()
        conn.close()

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

    conn = get_db_connection()
    cur = conn.cursor()
    cur.execute("SELECT id, username, email, department, role FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone()
    cur.close()
    conn.close()

    if row:
        return jsonify({'id': row[0], 'username': row[1], 'email': row[2], 'department': row[3], 'role': row[4]})
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
